import React, { useState, useEffect } from "react";
import Sidebar from "../shared/Sidebar";
import { adminApi } from "../../services/api";

export default function AdminApiLogs() {
  const [logs, setLogs] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [search, setSearch] = useState("");
  const [methodFilter, setMethodFilter] = useState("ALL");
  const [statusFilter, setStatusFilter] = useState("ALL");
  const [threatFilter, setThreatFilter] = useState("ALL");

  const fetchLogs = async () => {
    try {
      setError(null);
      const res = await adminApi.getRecentLogs();
      const data = res.data || [];
      setLogs(data);
      setFiltered(data);
    } catch (err) {
      const status = err.response?.status;
      if (status === 403) {
        setError("Access denied. Admin role required.");
      } else if (status === 404) {
        setError("API logs endpoint not found. Check backend configuration.");
      } else {
        setError(`Failed to load logs (${status || "network error"}). Check backend is running.`);
      }
      setLogs([]);
      setFiltered([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLogs();
    const t = setInterval(fetchLogs, 10000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    let data = [...logs];
    if (search) {
      data = data.filter(
        (l) =>
          (l.username || "").toLowerCase().includes(search.toLowerCase()) ||
          (l.endpoint || "").toLowerCase().includes(search.toLowerCase()) ||
          (l.ipAddress || "").toLowerCase().includes(search.toLowerCase())
      );
    }
    if (methodFilter !== "ALL") data = data.filter((l) => l.method === methodFilter);
    if (statusFilter !== "ALL") {
      if (statusFilter === "2xx") data = data.filter((l) => l.statusCode >= 200 && l.statusCode < 300);
      if (statusFilter === "4xx") data = data.filter((l) => l.statusCode >= 400 && l.statusCode < 500);
      if (statusFilter === "5xx") data = data.filter((l) => l.statusCode >= 500);
    }
    if (threatFilter === "THREAT") data = data.filter((l) => l.threatDetected);
    if (threatFilter === "CLEAN")  data = data.filter((l) => !l.threatDetected);
    setFiltered(data);
  }, [search, methodFilter, statusFilter, threatFilter, logs]);

  const totalRequests = logs.length;
  const threatCount   = logs.filter((l) => l.threatDetected).length;
  const errorCount    = logs.filter((l) => l.statusCode >= 400).length;
  const avgResponse   =
    logs.length > 0
      ? Math.round(
          logs.filter((l) => l.responseTimeMs).reduce((a, b) => a + (b.responseTimeMs || 0), 0) /
            logs.length
        )
      : 0;

  const formatTime = (ts) => {
    if (!ts) return "-";
    return new Date(ts).toLocaleTimeString("en-IN", {
      hour: "2-digit", minute: "2-digit", second: "2-digit",
    });
  };

  const truncate = (str, n) =>
    str && str.length > n ? str.substring(0, n) + "..." : str;

  const styles = {
    page: {
      display: "flex", minHeight: "100vh", background: "#050a14",
      fontFamily: "JetBrains Mono, monospace",
    },
    main: { flex: 1, padding: "24px", overflowY: "auto" },
    header: {
      display: "flex", justifyContent: "space-between",
      alignItems: "center", marginBottom: "24px",
    },
    title: { color: "#00d4ff", fontSize: "20px", fontWeight: 700 },
    subtitle: { color: "rgba(255,255,255,0.4)", fontSize: "12px", marginTop: "4px" },
    liveIndicator: {
      display: "flex", alignItems: "center", gap: "6px",
      color: "rgba(34,204,119,0.8)", fontSize: "11px",
    },
    liveDot: {
      width: "8px", height: "8px", borderRadius: "50%",
      background: "#22cc77",
    },
    refreshBtn: {
      background: "rgba(0,212,255,0.1)", border: "1px solid rgba(0,212,255,0.3)",
      borderRadius: "8px", color: "#00d4ff", padding: "8px 16px",
      cursor: "pointer", fontSize: "12px", fontFamily: "JetBrains Mono, monospace",
    },
    statsRow: {
      display: "grid", gridTemplateColumns: "repeat(4, 1fr)",
      gap: "16px", marginBottom: "24px",
    },
    statCard: (color) => ({
      background: "rgba(10,22,40,0.8)", border: `1px solid ${color}30`,
      borderRadius: "12px", padding: "16px", textAlign: "center",
    }),
    statNum: (color) => ({ color, fontSize: "28px", fontWeight: 700 }),
    statLabel: { color: "rgba(255,255,255,0.5)", fontSize: "11px", marginTop: "4px" },
    filters: {
      display: "flex", gap: "12px", marginBottom: "20px", flexWrap: "wrap",
    },
    searchInput: {
      flex: 1, minWidth: "200px", padding: "10px 14px",
      background: "rgba(255,255,255,0.05)", border: "1px solid rgba(255,255,255,0.1)",
      borderRadius: "8px", color: "#fff", fontSize: "12px",
      fontFamily: "JetBrains Mono, monospace", outline: "none",
    },
    select: {
      padding: "10px 14px", background: "rgba(255,255,255,0.05)",
      border: "1px solid rgba(255,255,255,0.1)", borderRadius: "8px",
      color: "#fff", fontSize: "12px", fontFamily: "JetBrains Mono, monospace",
      outline: "none", cursor: "pointer",
    },
    tableWrap: {
      background: "rgba(10,22,40,0.8)", border: "1px solid rgba(0,212,255,0.1)",
      borderRadius: "12px", overflow: "hidden",
    },
    table: { width: "100%", borderCollapse: "collapse" },
    thead: {
      background: "rgba(0,212,255,0.05)",
      borderBottom: "1px solid rgba(0,212,255,0.1)",
    },
    th: {
      padding: "12px 16px", textAlign: "left",
      color: "rgba(0,212,255,0.8)", fontSize: "11px",
      fontWeight: 600, letterSpacing: "1px",
    },
    tr: (threat) => ({
      borderBottom: "1px solid rgba(255,255,255,0.05)",
      background: threat ? "rgba(255,68,68,0.03)" : "transparent",
      transition: "background 0.2s",
    }),
    td: { padding: "12px 16px", color: "rgba(255,255,255,0.8)", fontSize: "12px" },
    methodBadge: (m) => {
      const colors = {
        GET: "#22cc77", POST: "#00d4ff", PUT: "#f59e0b",
        DELETE: "#ff4444", PATCH: "#a78bfa",
      };
      const c = colors[m] || "#888";
      return {
        background: `${c}20`, border: `1px solid ${c}40`,
        borderRadius: "4px", padding: "2px 8px",
        color: c, fontSize: "10px", fontWeight: 700,
      };
    },
    statusBadge: (s) => {
      const c = s >= 500 ? "#ff4444" : s >= 400 ? "#f59e0b" : "#22cc77";
      return {
        background: `${c}20`, border: `1px solid ${c}40`,
        borderRadius: "4px", padding: "2px 8px",
        color: c, fontSize: "11px", fontWeight: 700,
      };
    },
    threatBadge: {
      background: "rgba(255,68,68,0.15)", border: "1px solid rgba(255,68,68,0.4)",
      borderRadius: "4px", padding: "2px 8px",
      color: "#ff4444", fontSize: "10px", fontWeight: 700,
    },
    cleanBadge: {
      background: "rgba(34,204,119,0.15)", border: "1px solid rgba(34,204,119,0.4)",
      borderRadius: "4px", padding: "2px 8px",
      color: "#22cc77", fontSize: "10px",
    },
    threatTypeBadge: {
      background: "rgba(255,68,68,0.1)", border: "1px solid rgba(255,68,68,0.2)",
      borderRadius: "4px", padding: "2px 6px",
      color: "#ff6666", fontSize: "10px",
    },
    empty: {
      textAlign: "center", padding: "60px",
      color: "rgba(255,255,255,0.3)", fontSize: "14px",
    },
    errorBox: {
      textAlign: "center", padding: "40px",
      color: "#ff6666", fontSize: "13px",
      background: "rgba(255,68,68,0.05)",
      border: "1px solid rgba(255,68,68,0.2)",
      borderRadius: "8px", marginBottom: "20px",
    },
    footer: {
      marginTop: "12px", color: "rgba(255,255,255,0.3)",
      fontSize: "11px", textAlign: "right",
    },
  };

  return (
    <div style={styles.page}>
      <Sidebar role="ADMIN" />
      <div style={styles.main}>

        {/* Header */}
        <div style={styles.header}>
          <div>
            <div style={styles.title}>📋 API Logs</div>
            <div style={styles.subtitle}>Real-time request monitoring — last 1 hour</div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
            <div style={styles.liveIndicator}>
              <div style={styles.liveDot} />
              Live — refreshes every 10s
            </div>
            <button style={styles.refreshBtn} onClick={fetchLogs}>
              ↻ Refresh
            </button>
          </div>
        </div>

        {/* Error Banner */}
        {error && (
          <div style={styles.errorBox}>
            ⚠ {error}
            <br />
            <span style={{ fontSize: "11px", opacity: 0.7 }}>
              Check that the backend is running and the /api/admin/api-logs/recent endpoint exists with correct @PreAuthorize annotation.
            </span>
          </div>
        )}

        {/* Stats */}
        <div style={styles.statsRow}>
          <div style={styles.statCard("#00d4ff")}>
            <div style={styles.statNum("#00d4ff")}>{totalRequests}</div>
            <div style={styles.statLabel}>Total Requests</div>
          </div>
          <div style={styles.statCard("#ff4444")}>
            <div style={styles.statNum("#ff4444")}>{threatCount}</div>
            <div style={styles.statLabel}>Threats Detected</div>
          </div>
          <div style={styles.statCard("#f59e0b")}>
            <div style={styles.statNum("#f59e0b")}>{errorCount}</div>
            <div style={styles.statLabel}>Error Responses</div>
          </div>
          <div style={styles.statCard("#22cc77")}>
            <div style={styles.statNum("#22cc77")}>{avgResponse}ms</div>
            <div style={styles.statLabel}>Avg Response Time</div>
          </div>
        </div>

        {/* Filters */}
        <div style={styles.filters}>
          <input
            style={styles.searchInput}
            placeholder="🔍 Search by username, endpoint or IP..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          <select
            style={styles.select}
            value={methodFilter}
            onChange={(e) => setMethodFilter(e.target.value)}
          >
            <option value="ALL">All Methods</option>
            <option value="GET">GET</option>
            <option value="POST">POST</option>
            <option value="PUT">PUT</option>
            <option value="DELETE">DELETE</option>
          </select>
          <select
            style={styles.select}
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
          >
            <option value="ALL">All Status</option>
            <option value="2xx">2xx Success</option>
            <option value="4xx">4xx Client Error</option>
            <option value="5xx">5xx Server Error</option>
          </select>
          <select
            style={styles.select}
            value={threatFilter}
            onChange={(e) => setThreatFilter(e.target.value)}
          >
            <option value="ALL">All Requests</option>
            <option value="THREAT">Threats Only</option>
            <option value="CLEAN">Clean Only</option>
          </select>
        </div>

        {/* Table */}
        <div style={styles.tableWrap}>
          {loading ? (
            <div style={styles.empty}>Loading logs...</div>
          ) : filtered.length === 0 ? (
            <div style={styles.empty}>
              {error ? "Could not load logs." : "No logs found for the selected filters."}
            </div>
          ) : (
            <table style={styles.table}>
              <thead style={styles.thead}>
                <tr>
                  <th style={styles.th}>TIME</th>
                  <th style={styles.th}>USER</th>
                  <th style={styles.th}>METHOD</th>
                  <th style={styles.th}>ENDPOINT</th>
                  <th style={styles.th}>STATUS</th>
                  <th style={styles.th}>RESPONSE TIME</th>
                  <th style={styles.th}>IP ADDRESS</th>
                  <th style={styles.th}>THREAT</th>
                  <th style={styles.th}>THREAT TYPE</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((log, i) => (
                  <tr
                    key={log.id || i}
                    style={styles.tr(log.threatDetected)}
                    onMouseEnter={(e) =>
                      (e.currentTarget.style.background = log.threatDetected
                        ? "rgba(255,68,68,0.08)"
                        : "rgba(255,255,255,0.02)")
                    }
                    onMouseLeave={(e) =>
                      (e.currentTarget.style.background = log.threatDetected
                        ? "rgba(255,68,68,0.03)"
                        : "transparent")
                    }
                  >
                    <td style={{ ...styles.td, color: "rgba(255,255,255,0.4)", fontSize: "11px" }}>
                      {formatTime(log.timestamp)}
                    </td>
                    <td style={styles.td}>
                      <span style={{ color: "#00d4ff" }}>
                        {log.username || "anonymous"}
                      </span>
                    </td>
                    <td style={styles.td}>
                      <span style={styles.methodBadge(log.method)}>{log.method}</span>
                    </td>
                    <td style={{ ...styles.td, maxWidth: "200px" }}>
                      <span title={log.endpoint}>{truncate(log.endpoint, 35)}</span>
                    </td>
                    <td style={styles.td}>
                      <span style={styles.statusBadge(log.statusCode)}>
                        {log.statusCode}
                      </span>
                    </td>
                    <td style={styles.td}>
                      <span
                        style={{
                          color:
                            log.responseTimeMs > 2000
                              ? "#f59e0b"
                              : "rgba(255,255,255,0.6)",
                        }}
                      >
                        {log.responseTimeMs ? `${log.responseTimeMs}ms` : "-"}
                      </span>
                    </td>
                    <td style={{ ...styles.td, color: "rgba(255,255,255,0.5)", fontSize: "11px" }}>
                      {log.ipAddress || "-"}
                    </td>
                    <td style={styles.td}>
                      {log.threatDetected ? (
                        <span style={styles.threatBadge}>⚠ THREAT</span>
                      ) : (
                        <span style={styles.cleanBadge}>✓ CLEAN</span>
                      )}
                    </td>
                    <td style={styles.td}>
                      {log.threatType ? (
                        <span style={styles.threatTypeBadge}>{log.threatType}</span>
                      ) : (
                        <span style={{ color: "rgba(255,255,255,0.2)" }}>—</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        {/* Footer */}
        <div style={styles.footer}>
          Showing {filtered.length} of {logs.length} requests
        </div>
      </div>
    </div>
  );
}
